/* cppi::4beccf7178e76ae98a93855c40bf2ba55caae249121ae4c48031d32aa5f54274 */
--select maturity_dt, * from df_trusted_prod.mds_csl_daily_history where id_cppibsec in (29130615,25968787) order by business_date desc limit 100
--TICKER_EXCH_CD	TYP	ID_CPPIBSEC	 ID_BB_UNIQUE	SEC_SHRT_NME
/*
select max(max_business_date) as max_business_date, max(prev_business_date) as prev_business_date 
from 
(
select max(business_date) as max_business_date, date('2000-01-01') as prev_business_date
from df_trusted_prod.mds_csl_daily_history cxhist
union
select date('2000-01-01') as max_business_date, max(business_date) as prev_business_date
from df_trusted_prod.mds_csl_daily_history cxhist2
where cxhist2.business_date < (select max(business_date) 
from df_trusted_prod.mds_csl_daily_history cxhist3)
) xx;
*/

with cslDates as (
    select max(business_date) as business_dt, min(business_date) as previous_business_dt
    from (
        select distinct(business_date) from df_trusted_prod.mds_csl_daily_history order by business_date desc limit 2
    )
)
select * from df_trusted_prod.mds_csl_daily_history his
join cslDates cDates on his.business_date = cDates.business_dt
where business_date between cDates.business_dt and cDates.previous_business_dt

